        "language": "python",
        "filename": "orchestrator/bounded_rag_router.py",
        "description": "Minh họa bộ định tuyến Agentic RAG kiểm soát chặt vòng lặp và chi phí: kiểm tra quy tắc bypass Semantic Cache, phân tích định tuyến JSON cấu trúc, thực thi song song hàm PostgreSQL Live có `SET LOCAL` FORCE RLS và tìm kiếm Vector tài liệu hiệu lực.",
        "code": "import asyncio\nfrom typing import Optional\nfrom pydantic import BaseModel, Field\nimport asyncpg\n\nLIVE_ENTITY_HINTS = (\"còn không\", \"trống không\", \"tồn kho\", \"giữ chỗ\", \"đơn hàng\", \"cọc\")\n\nclass RoutePlan(BaseModel):\n    need_live_sql: bool = Field(..., description=\"True nếu cần kiểm tra tồn kho, trạng thái căn/SKU hoặc đơn hàng sống\")\n    need_policy_vector: bool = Field(..., description=\"True nếu cần tra điều khoản, chiết khấu hoặc quy chế PDF\")\n    extracted_sku_or_unit: Optional[str] = Field(None, description=\"Mã căn hộ hoặc SKU nếu khách nhắc tới, vd: B3-08\")\n    rewritten_policy_query: Optional[str] = Field(None, description=\"Truy vấn chuẩn hóa để tìm điều khoản PDF\")\n\ndef should_bypass_semantic_cache(user_query: str) -> bool:\n    lowered = user_query.lower()\n    return any(hint in lowered for hint in LIVE_ENTITY_HINTS)\n\nasync def fetch_live_unit_status(pool: asyncpg.Pool, tenant_id: str, unit_code: str) -> dict:\n    \"\"\"Truy vấn PostgreSQL Live bằng hàm tham số hóa có FORCE RLS & timeout cứng.\"\"\"\n    async with pool.acquire() as conn:\n        async with conn.transaction(readonly=True):\n            await conn.execute(\"SET LOCAL statement_timeout = '450ms'\")\n            await conn.execute(\"SET LOCAL app.current_tenant_id = $1\", tenant_id)\n            row = await conn.fetchrow(\n                \"\"\"\n                SELECT unit_code, availability_status, list_price_vnd, updated_at\n                FROM inventory_units\n                WHERE unit_code = UPPER($1)\n                LIMIT 1\n                \"\"\",\n                unit_code,\n            )\n            return dict(row) if row else {\"unit_code\": unit_code, \"availability_status\": \"NOT_FOUND\"}\n\nasync def fetch_hybrid_policy_chunks(tenant_id: str, query_text: str) -> tuple[list[str], float]:\n    \"\"\"Gọi Qdrant/pgvector Hybrid Search có bộ lọc cứng status='active', trả về (chunks, top1_score).\"\"\"\n    # Triển khai BM25 + Dense Vector RRF + Reranker tại đây\n    return [\"Chiết khấu thanh toán nhanh 6 đợt là 5% áp dụng đến 30/11/2026.\"], 0.89\n\nasync def bounded_agentic_rag(\n    user_query: str,\n    tenant_id: str,\n    pg_pool: asyncpg.Pool,\n    plan: RoutePlan,\n) -> dict:\n    if not should_bypass_semantic_cache(user_query) and not plan.need_live_sql:\n        # Có thể tra Redis/Qdrant Semantic Cache trước tại đây để tiết kiệm 60% token\n        pass\n\n    tasks = []\n    live_task = (\n        fetch_live_unit_status(pg_pool, tenant_id, plan.extracted_sku_or_unit)\n        if plan.need_live_sql and plan.extracted_sku_or_unit\n        else asyncio.sleep(0, result=None)\n    )\n    policy_task = (\n        fetch_hybrid_policy_chunks(tenant_id, plan.rewritten_policy_query or user_query)\n        if plan.need_policy_vector\n        else asyncio.sleep(0, result=([], 1.0))\n    )\n\n    live_data, (policy_chunks, top1_score) = await asyncio.gather(live_task, policy_task)\n\n    # Bounded Self-Correction: tối đa 1 nhịp Query Rewrite nếu điểm ngữ cảnh PDF quá thấp\n    if plan.need_policy_vector and top1_score < 0.48:\n        policy_chunks, top1_score = await fetch_hybrid_policy_chunks(tenant_id, f\"quy chế bán hàng {user_query}\")\n        if top1_score < 0.45:\n            return {\"action\": \"HANDOFF_ZALOBOT_SALE\", \"live_data\": live_data, \"reason\": \"low_policy_confidence\"}\n\n    return {\n        \"action\": \"SYNTHESIZE_ANSWER\",\n        \"live_data\": live_data,\n        \"policy_chunks\": policy_chunks,\n    }"
